describe('onError', () => {
  const captureOnError = async (reason: unknown) => {
    let received: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_s, e) => {
        received = e;
      },
    };
    const orchestrator = createChatOrchestrator(rejectingProvider(reason), promptBuilder, undefined, {hooks});
    const rejection = await orchestrator.processMessage(createSession('hello')).catch(e => e);
    return {rejection, received};
  };

  it('called with session and error when stream fails', async () => {
    const callOrder: string[] = [];
    const hooks: OrchestratorHooks = {
      onError: async (session, error) => {
        callOrder.push('onError');
        expect(session.sessionId).toBe('s1');
        expect(error.message).toBe('rate limited');
      },
    };

    const orchestrator = createChatOrchestrator(
      {
        // eslint-disable-next-line require-yield
        async *sendMessage(): AsyncGenerator<MessageChunk> {
          throw new AIError('rate limited', 'RATE_LIMITED');
        },
        async generateStructured<T>(): Promise<T> {
          return {} as T;
        },
      },
      promptBuilder,
      undefined,
      {hooks}
    );

    const result = await orchestrator.processMessage(createSession('hello')).catch(e => e);

    expect({
      callOrder,
      outcome: result.message,
      receivedErrorMessage: result.message,
    }).toEqual({
      callOrder: ['onError'],
      outcome: 'rate limited',
      receivedErrorMessage: 'rate limited',
    });
  });

  it('error still propagates after onError hook', async () => {
    const hooks: OrchestratorHooks = {
      onError: async () => {},
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
  });

  it('coerces non-Error rejections to Error for onError hook', async () => {
    const {rejection, received} = await captureOnError('string boom');
    expect({
      rejection,
      isError: received instanceof Error,
      message: received?.message,
      cause: received?.cause,
    }).toEqual({
      rejection: 'string boom',
      isError: true,
      message: 'string boom',
      cause: 'string boom',
    });
  });

  it('coerces undefined rejection to Error for onError hook', async () => {
    const {rejection, received} = await captureOnError(undefined);
    expect({
      rejection,
      isError: received instanceof Error,
      message: received?.message,
      cause: received?.cause,
    }).toEqual({
      rejection: undefined,
      isError: true,
      message: 'undefined',
      cause: undefined,
    });
  });

  it('passes through Error instance to onError without wrapping', async () => {
    const originalError = new Error('original');
    const {rejection, received} = await captureOnError(originalError);
    expect({rejection, received}).toEqual({rejection: originalError, received: originalError});
  });
});

